/** Embedded runtime assets (generated by scripts/build.mjs) and lazy decoders. */
import {wasmBase64, lexiconBase64, workletSource} from '../generated/assets';
import {decodeLexicon, EMPTY_LEXICON, type Lexicon} from '../core/text';

const decode = (b64: string) => Uint8Array.from(atob(b64), c => c.charCodeAt(0));

let wasmModule: WebAssembly.Module | null = null;
let wasmBytes: Uint8Array | null = null;
export function engineBytes(): Uint8Array {
  return (wasmBytes ??= decode(wasmBase64));
}
export function engineModule(): WebAssembly.Module {
  return (wasmModule ??= new WebAssembly.Module(engineBytes() as BufferSource));
}
export {workletSource};

let lexicon: Promise<Lexicon> | null = null;
/** The pronunciation dictionary, decompressed on first use. */
export function loadLexicon(): Promise<Lexicon> {
  return (lexicon ??= (async () => {
    try {
      const stream = new Blob([decode(lexiconBase64) as BlobPart]).stream().pipeThrough(new DecompressionStream('gzip'));
      return decodeLexicon(await new Response(stream).text());
    } catch {
      return EMPTY_LEXICON;
    }
  })());
}
